class LeoOperatorKeyKeyabilityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@EnumSource(Shape.class)
	void unauditedSourcesDeclineBeforeOpeningRowsOrInferringHeaders(Shape shape) {
		for (boolean declared : new boolean[] { false, true }) {
			for (LeoOperatorKey.ConstantMode mode : LeoOperatorKey.ConstantMode.values()) {
				SingleUseRows rows = new SingleUseRows();
				TupleExpr expression = shape.wrap(assignment(rows, declared));
				assertAll(shape + ", declared=" + declared + ", mode=" + mode,
						() -> assertThrows(LeoOperatorKey.UnkeyableOperatorException.class,
								() -> LeoOperatorKey.from(expression, "", mode)),
						() -> assertEquals(0, rows.opened.get(), "key generation must not open caller-owned rows"));
			}
		}
	}

	@ParameterizedTest
	@EnumSource(Shape.class)
	void inputShapeDeclinesWithoutOpeningUnauditedRows(Shape shape) {
		for (boolean declared : new boolean[] { false, true }) {
			for (Set<String> inputs : List.of(Set.<String>of(), Set.of("x"))) {
				SingleUseRows rows = new SingleUseRows();
				TupleExpr expression = shape.wrap(assignment(rows, declared));
				assertAll(shape + ", declared=" + declared + ", inputs=" + inputs,
						() -> assertThrows(LeoOperatorKey.UnkeyableOperatorException.class,
								() -> LeoOperatorKey.alphaNormalizedInputBindingShape(expression, inputs)),
						() -> assertEquals(0, rows.opened.get(), "input shape must not open caller-owned rows"));
			}
		}
	}

	@Test
	void equalUnauditedOccurrencesEachDeclineWithoutAnOpaqueContentAlias() {
		SingleUseRows firstRows = new SingleUseRows();
		SingleUseRows secondRows = new SingleUseRows();
		BindingSetAssignment first = assignment(firstRows, true);
		BindingSetAssignment second = assignment(secondRows, true);
		assertEquals(first, second, "equal source objects do not prove repeatable evaluation occurrences");

		assertAll(
				() -> assertThrows(LeoOperatorKey.UnkeyableOperatorException.class, () -> LeoOperatorKey.from(first)),
				() -> assertThrows(LeoOperatorKey.UnkeyableOperatorException.class, () -> LeoOperatorKey.from(second)),
				() -> assertEquals(0, firstRows.opened.get()),
				() -> assertEquals(0, secondRows.opened.get()));
	}

	@Test
	void mutableRowsAndAbsentSourcesHaveNoStableContentKey() {
		MapBindingSet mutable = new MapBindingSet();
		mutable.addBinding("x", VF.createLiteral("first"));
		BindingSetAssignment mutableAssignment = assignment(List.of(mutable), true);
		BindingSetAssignment absentSource = assignment(null, true);

		assertAll(
				() -> assertThrows(LeoOperatorKey.UnkeyableOperatorException.class,
						() -> LeoOperatorKey.from(mutableAssignment)),
				() -> assertThrows(LeoOperatorKey.UnkeyableOperatorException.class,
						() -> LeoOperatorKey.from(absentSource)));
	}

	@Test
	void unknownAssignmentImplementationDeclinesWithoutReadingItsSourceOrHeader() {
		BindingSetAssignment unknown = new BindingSetAssignment() {
			@Override
			public Iterable<BindingSet> getBindingSets() {
				throw new AssertionError("unknown source must not be inspected");
			}

			@Override
			public Set<String> getBindingNames() {
				throw new AssertionError("unknown header must not be inferred");
			}
		};
		assertThrows(LeoOperatorKey.UnkeyableOperatorException.class, () -> LeoOperatorKey.from(unknown));
	}

	@Test
	void auditedImmutableFiniteRowsKeepExactContentKeys() {
		BindingSet first = row("first");
		BindingSet second = row("second");
		BindingSet nullable = new ListBindingSet(List.of("x", "y"), Arrays.asList(VF.createLiteral("first"), null));
		BindingSetAssignment empty = assignment(List.of(), true);
		BindingSetAssignment singleton = assignment(List.of(first), true);
		BindingSetAssignment multiple = assignment(List.of(first, second, first), true);
		BindingSetAssignment reordered = assignment(new CertifiedRows(List.of(second, first, first)), true);

		assertEquals(LeoOperatorKey.from(multiple), LeoOperatorKey.from(reordered));
		assertEquals(LeoOperatorKey.from(multiple), LeoOperatorKey.from(multiple.clone()));
		assertEquals(LeoOperatorKey.from(empty), LeoOperatorKey.from(assignment(new CertifiedRows(List.of()), true)));
		assertNotEquals(LeoOperatorKey.from(empty), LeoOperatorKey.from(singleton));
		assertNotEquals(LeoOperatorKey.from(singleton), LeoOperatorKey.from(multiple));
		assertEquals(LeoOperatorKey.from(assignment(List.of(nullable), false)),
				LeoOperatorKey.from(assignment(new CertifiedRows(List.of(nullable)), false)));
		assertNotEquals(LeoOperatorKey.from(assignment(List.of(), false)),
				LeoOperatorKey.from(assignment(List.of(EmptyBindingSet.getInstance()), false)),
				"an empty relation differs from the singleton empty mapping");
		assertNotEquals(LeoOperatorKey.from(assignment(List.of(EmptyBindingSet.getInstance()), false)),
				LeoOperatorKey.from(assignment(
						List.of(EmptyBindingSet.getInstance(), EmptyBindingSet.getInstance()), false)));
		assertNotEquals("BSA|arity=0|columns=|rows=",
				LeoOperatorKey.from(assignment(List.of(), false)).structuralFingerprint(),
				"the old ambiguous persisted identity cannot match a new zero-column content key");
	}

	@Test
	void largeImmutableTablesKeepDigestReuseAndExactDuplicateMultiplicity() {
		List<BindingSet> rows = new ArrayList<>();
		for (int ordinal = 0; ordinal < 40; ordinal++) {
			rows.add(row("row-" + ordinal));
		}
		List<BindingSet> reordered = new ArrayList<>(rows);
		Collections.reverse(reordered);
		LeoOperatorKey first = LeoOperatorKey.from(assignment(rows, true));
		assertEquals(first, LeoOperatorKey.from(assignment(reordered, true)));
		assertTrue(first.structuralFingerprint().contains("|rowCount=40|rows=digest128="));
		rows.add(rows.get(0));
		LeoOperatorKey duplicate = LeoOperatorKey.from(assignment(rows, true));
		assertNotEquals(first, duplicate);
		assertTrue(duplicate.structuralFingerprint().contains("|rowCount=41|rows=digest128="));
	}

	private static BindingSetAssignment assignment(Iterable<BindingSet> rows, boolean declared) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		if (declared) {
			assignment.setDeclaredBindingNames(Set.of("x"));
		}
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static BindingSet row(String label) {
		return new ListBindingSet(List.of("x"), VF.createLiteral(label));
	}

	private record CertifiedRows(List<BindingSet> rows) implements BindingSetAssignment.RepeatableBindingSetSource {
		@Override
		public Iterator<BindingSet> iterator() {
			return rows.iterator();
		}
	}

	private static final class SingleUseRows implements Iterable<BindingSet> {
		private final AtomicInteger opened = new AtomicInteger();

		@Override
		public Iterator<BindingSet> iterator() {
			return opened.getAndIncrement() == 0 ? List.of(row("first"), row("second")).iterator()
					: List.<BindingSet>of().iterator();
		}

		@Override
		public boolean equals(Object other) {
			return other instanceof SingleUseRows;
		}

		@Override
		public int hashCode() {
			return 1;
		}
	}

	private enum Shape {
		DIRECT,
		FILTER,
		UNION,
		OPTIONAL,
		MINUS,
		EXISTS,
		SUBQUERY,
		NESTED;

		TupleExpr wrap(BindingSetAssignment source) {
			return switch (this) {
			case DIRECT -> source;
			case FILTER -> new Filter(source, new Bound(new Var("x")));
			case UNION -> new Union(new SingletonSet(), source);
			case OPTIONAL -> new LeftJoin(new SingletonSet(), source);
			case MINUS -> new Difference(new SingletonSet(), source);
			case EXISTS -> new Filter(new SingletonSet(), new Exists(source));
			case SUBQUERY -> new Projection(source, new ProjectionElemList(new ProjectionElem("x")));
			case NESTED -> new QueryRoot(new Filter(new Join(new SingletonSet(),
					new LeftJoin(new SingletonSet(), new Union(new SingletonSet(), source))), new Bound(new Var("x"))));
			};
		}
	}
}
